<?php declare(strict_types=1); namespace Annam; $title='WhatsApp inbox';$subtitle='Customer conversations · incoming messages, automation and staff replies.';$body_class='wa-page';$actions='<a class="o-btn" href="/manage/whatsapp/settings/">Connection settings</a>'; ?>
<?php if(!$has_connection): ?><div class="wa-setup"><strong>Connect your WhatsApp number</strong><p>Add your Meta phone number ID and n8n inbox sync token to start receiving conversations. Existing n8n automation can stay active.</p><a href="/manage/whatsapp/settings/">Open connection settings →</a></div><?php endif; ?>
<div class="wa-inbox <?= $conversation?'wa-selected':'' ?>" data-inbox data-poll="<?= $message_page===1?'1':'0' ?>"><aside class="wa-contacts"><header><div><h2>Conversations</h2><span id="wa-unread-total"><?= e($unread_total) ?> unread messages</span></div><a href="/manage/whatsapp/settings/" aria-label="WhatsApp connection settings">⚙</a></header><form method="get" action="/manage/whatsapp/" class="wa-search"><input class="o-input" name="q" value="<?= e($query) ?>" placeholder="Search name or phone" aria-label="Search conversations"><button class="o-btn">Search</button></form><div id="wa-contact-list"><?php foreach($conversations as $chat): ?><a class="wa-contact <?= ($conversation['id']??null)===$chat['id']?'is-selected':'' ?>" href="/manage/whatsapp/<?= e($chat['id']) ?>/"><span class="wa-avatar"><?= e(mb_strtoupper(mb_substr($chat['display_name']?:$chat['phone'],0,1))) ?></span><div><strong><?= e($chat['display_name']?:$chat['phone']) ?></strong><p><?= e($chat['preview']) ?></p></div><?php if($chat['unread_count']): ?><b class="wa-unread"><?= e($chat['unread_count']) ?></b><?php endif; ?></a><?php endforeach; ?><?php if(!$conversations): ?><div class="wa-contact-empty"><strong><?= $query?'No matching conversations':'No conversations yet' ?></strong><p>Incoming messages will appear here once connected. Old WhatsApp history is not automatically imported.</p></div><?php endif; ?><?php if($contact_pages>1): ?><nav class="wa-pagination" aria-label="Conversation pages"><?php if($contact_page>1): ?><a href="?<?= e(http_build_query(['contacts_page'=>$contact_page-1,'q'=>$query])) ?>">Previous</a><?php endif; ?><span><?= e($contact_page) ?> / <?= e($contact_pages) ?></span><?php if($contact_page<$contact_pages): ?><a href="?<?= e(http_build_query(['contacts_page'=>$contact_page+1,'q'=>$query])) ?>">Next</a><?php endif; ?></nav><?php endif; ?></div></aside>
<section class="wa-chat" aria-label="Customer conversation"><?php if($conversation): $canReply=$reply_ready&&$conversation['last_inbound_at']&&strtotime($conversation['last_inbound_at'])>time()-86400; ?><header class="wa-chat-head"><a class="wa-back" href="/manage/whatsapp/">← All chats</a><div class="wa-avatar"><?= e(mb_strtoupper(mb_substr($conversation['display_name']?:$conversation['phone'],0,1))) ?></div><div class="wa-person"><h2><?= e($conversation['display_name']?:$conversation['phone']) ?></h2><span>+<?= e($conversation['phone']) ?></span><small><?= $canReply?'24-hour reply window is open':'Reply window closed — customer must message again' ?></small></div><a class="o-btn" href="/billing/new/?<?= e(http_build_query(['channel'=>'whatsapp','phone'=>$conversation['phone'],'name'=>$conversation['display_name']])) ?>">Create order</a><form method="post" action="read/"><?= csrf() ?><button class="o-btn">Mark as read</button></form></header><div class="wa-thread" tabindex="0" aria-label="Message history"><div id="wa-message-list"><?php if($message_page>1): ?><div class="wa-pagination"><a href="?page=<?= e($message_page-1) ?>">Newer messages →</a></div><?php endif; ?><?php if($message_page*50<$message_total): ?><div class="wa-pagination"><a href="?page=<?= e($message_page+1) ?>">← Older messages</a></div><?php endif; ?><?php foreach($messages as $message): ?><article class="wa-bubble <?= in_array($message['direction'],['out','outbound'],true)?'wa-out':'wa-in' ?>"><p><?= nl2br(e($message['body'])) ?></p><?php if($message['media_id']): ?><a href="/manage/whatsapp/messages/<?= e($message['id']) ?>/media/">View attachment</a><?php endif; ?><small><?= e(date('j M, g:i A',strtotime($message['occurred_at'])).' · '.$message['status']) ?></small></article><?php endforeach; ?></div></div><form method="post" action="reply/" class="wa-compose"><?= csrf() ?><input name="token" type="hidden" value="<?= e($token) ?>"><label for="wa-reply">Reply to customer</label><div><textarea id="wa-reply" name="body" rows="2" required maxlength="1024" placeholder="Type a message…" <?= !$canReply?'disabled':'' ?>></textarea><button class="o-btn o-btn-primary" <?= !$canReply?'disabled':'' ?>>Send reply</button></div><small><?= !$reply_ready?'Staff sending is not connected. Replies from your n8n automation will still appear here.':(!$canReply?"Free-text replies are allowed only within 24 hours of the customer's last message.":'Sent through your configured WhatsApp sender. Automation remains in n8n.') ?></small></form><?php else: ?><div class="wa-welcome"><span>☏</span><h2>Your WhatsApp conversations</h2><p>Select a customer to view messages and order requests. New messages appear here once n8n or the verified Meta webhook is connected.</p><a class="o-btn" href="/manage/whatsapp/settings/">Connect WhatsApp</a></div><?php endif; ?></section></div><p class="wa-poll-note" id="wa-poll-note" role="status">Updates automatically while this page is open.</p><script src="<?= e(asset_url('admin-inbox.js')) ?>" defer></script>
